-- Settings → Roles → "Assign me to the cases I create" (auto_assign_creator). The creator of a case
-- can add their own assignment to it when their role has the permission. Before, only admin/manager
-- could write case_assignments, so the automatic assignment of the creating consultant failed silently.
CREATE OR REPLACE FUNCTION public.role_permission_defaults()
RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$
  SELECT '{"create_cases":{"admin":true,"manager":true,"client":true,"key_user":true,"internal_consultant":true,"project_manager":true},"view_all_cases":{"admin":true,"manager":true,"project_manager":true},"approve_specs":{"admin":true,"manager":true,"project_manager":true},"regen_specs":{"admin":true,"manager":true},"upload_docs":{"admin":true,"manager":true,"consultant":true,"internal_consultant":true,"project_manager":true},"delete_docs":{"admin":true,"manager":true},"delete_own_docs":{"admin":true,"manager":true},"view_docs":{"admin":true,"manager":true,"consultant":true,"client":true,"key_user":true,"final_user":true,"internal_consultant":true,"project_manager":true},"add_activities":{"admin":true,"manager":true,"consultant":true,"internal_consultant":true,"project_manager":true},"log_time":{"admin":true,"manager":true,"consultant":true,"internal_consultant":true},"apply_to_cases":{"consultant":true,"headhunter":true},"view_reports":{"admin":true,"manager":true,"client":true,"project_manager":true},"manage_invoices":{"admin":true,"manager":true,"client":true},"view_lifecycle":{"admin":true,"manager":true,"consultant":true,"client":true,"final_user":true,"internal_consultant":true,"project_manager":true},"submit_specs":{"admin":true,"manager":true,"consultant":true,"client":true,"key_user":true,"internal_consultant":true,"project_manager":true},"generate_dev_plan":{"admin":true,"manager":true,"consultant":true},"require_team_signup":{"key_user":true,"final_user":true,"internal_consultant":true,"project_manager":true},"edit_activity_phase":{"admin":true,"manager":true,"consultant":true,"internal_consultant":true,"project_manager":true},"edit_activity_predecessors":{"admin":true,"manager":true,"consultant":true,"internal_consultant":true,"project_manager":true},"bulk_delete_activities":{"admin":true,"manager":true},"bulk_delete_subcases":{"admin":true,"manager":true},"arena_see_all_cases":{"admin":true,"manager":true,"consultant":true,"headhunter":true,"internal_consultant":true,"project_manager":true},"create_projects":{"admin":true,"manager":true,"client":true,"project_manager":true},"view_audit_log":{"admin":true,"manager":true},"reopen_cases":{"admin":true,"manager":true,"project_manager":true},"edit_lifecycle":{"admin":true,"manager":true,"project_manager":true},"export_pdf_docs":{"admin":true,"manager":true,"consultant":true,"client":true,"key_user":true,"internal_consultant":true,"project_manager":true},"manage_proposals":{"admin":true},"manage_own_project_proposals":{"admin":true,"manager":true,"client":true,"project_manager":true,"area_leader":true},"upload_project_docs":{"admin":true,"manager":true,"project_manager":true},"run_sap_implementation":{"admin":true,"manager":true,"consultant":true},"edit_sap_setup":{"admin":true,"manager":true},"release_transports":{"admin":true,"manager":true,"consultant":true},"confirm_transport_imports":{"admin":true,"manager":true,"project_manager":true},"approve_asbuilt_spec":{"admin":true,"manager":true,"project_manager":true},"add_subcases":{"admin":true,"manager":true,"client":true},"view_case_costs":{"admin":true,"manager":true},"change_case_sap_env":{"admin":true,"manager":true},"invite_case_client":{"admin":true,"manager":true,"consultant":true},"manage_case_consultants":{"admin":true,"manager":true},"save_as_template":{"admin":true,"manager":true},"manage_milestones":{"admin":true,"manager":true,"consultant":true},"post_internal_comments":{"admin":true,"manager":true},"approve_time":{"admin":true,"manager":true},"delete_time_entries":{"admin":true,"manager":true},"bulk_edit_cases":{"admin":true,"manager":true},"move_kanban_cards":{"admin":true,"manager":true},"manage_sla":{"admin":true,"manager":true},"manage_db_connections":{"admin":true,"manager":true},"manage_team_members":{"admin":true,"manager":true},"auto_assign_creator":{"consultant":true},"manage_migrations":{"admin":true,"manager":true}}'::jsonb
$$;

-- SECURITY DEFINER helper: a subquery on cases inside a case_assignments policy recurses
-- (the cases policies read case_assignments).
CREATE OR REPLACE FUNCTION public.is_case_creator(p_case uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM cases WHERE id = p_case AND created_by = auth.uid())
$$;
REVOKE ALL ON FUNCTION public.is_case_creator(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.is_case_creator(uuid) TO authenticated;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'case_assignments' AND policyname = 'ca_self_assign_creator') THEN
    CREATE POLICY ca_self_assign_creator ON public.case_assignments FOR INSERT TO authenticated
      WITH CHECK (consultant_id = auth.uid() AND public.has_capability('auto_assign_creator') AND public.is_case_creator(case_id));
  END IF;
END $$;
ALTER POLICY ca_self_assign_creator ON public.case_assignments
  WITH CHECK (consultant_id = auth.uid() AND public.has_capability('auto_assign_creator') AND public.is_case_creator(case_id));
